using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RewardSetup", menuName = "Data/BattleSceneSetups/RewardSetup", order = 0)]
public class RewardSetup : BattleSceneSetup
{
	[SerializeField]
	private VoidEvent OnDisableTurnCounterText;

	public override void SetupScene()
	{
		base.SetupScene();
		OnDisableTurnCounterText.Raise();
		ReferenceSingleton<GameStateManager>.Instance.SetPlayerRewardStateState();
		if (mapHandler.CurrentReward != null)
		{
			mapHandler.CurrentReward.InstantiatePropPrefab();
			if (!(mapHandler.CurrentReward is ShrineClearingReward))
			{
				GoToEndOfBattleState();
			}
		}
		else
		{
			GoToEndOfBattleState();
		}
		void GoToEndOfBattleState()
		{
			bool flag = false;
			if (ReferenceSingleton<GameplayHandler>.Instance.DisableRewardsAnimation)
			{
				flag = true;
			}
			else if (mapHandler.CurrentReward != null && mapHandler.CurrentReward.Rewards.First() is CompanionReward)
			{
				flag = true;
			}
			if (!flag)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.5f, delegate
				{
					ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
				});
			}
			else
			{
				ReferenceSingleton<GameStateManager>.Instance.SetEndOfBattleStateWithQueueLockFalse();
			}
		}
	}
}
